function favicon37(t){const d=issuerDomain37[t]||'zse.co.zw';return `https://www.google.com/s2/favicons?domain=${encodeURIComponent(d)}&sz=128`}
function logoUrl37(t){return logoDirect37[t]||favicon37(t)}
function neutralLogo37(){return `data:image/svg+xml;charset=utf-8,${encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#eef3fb"/><path d="M14 47h36M18 43V25l14-9 14 9v18M24 43V29h5v14M35 43V29h5v14" fill="none" stroke="#3158e8" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>')}`}
function setRealLogo37(img,t){if(!img||!t)return;img.classList.add('v37-issuer-logo','v36-issuer-logo');img.alt=`${issuerName37[t]||t} logo`;img.referrerPolicy='no-referrer';img.dataset.ticker=t;img.dataset.fallback='0';img.onerror=()=>{if(img.dataset.fallback==='0'&&logoDirect37[t]){img.dataset.fallback='1';img.src=favicon37(t)}else{img.onerror=null;img.src=neutralLogo37()}};img.src=logoUrl37(t)}
function currentTicker37(){return ($('#page-orders .v33-security-head h2')?.textContent||'DLTA').split('·')[0].trim().replace(/\.(ZW|VX)$/,'')}
function currentSecurity37(){const head=$('#page-orders .v33-security-head'),ticker=currentTicker37(),price=num(head?.querySelector('.v33-price strong')?.textContent)||0,currency=(head?.querySelector('.v33-price strong')?.textContent||'ZWG').trim().split(/\s+/)[0],name=(head?.querySelector('h2')?.textContent||issuerName37[ticker]||ticker).split('·').slice(1).join('·').trim()||issuerName37[ticker]||ticker,market=(head?.querySelector('.v33-kicker')?.textContent||'Listed security').split('·')[0].trim();return{ticker,name,price,currency,market}}
function decorateIssuerLogos37(){const list=$('#page-orders #v33InstrumentList');if(list)$$('.v33-instrument',list).forEach(row=>{const t=(row.querySelector('strong')?.textContent||'').trim().replace(/\.(ZW|VX)$/,'');if(!t)return;let img=row.querySelector('img.v37-issuer-logo,img.v36-issuer-logo');if(!img){img=document.createElement('img');row.insertBefore(img,row.firstChild)}if(img.dataset.ticker!==t||!img.classList.contains('v37-issuer-logo'))setRealLogo37(img,t);row.querySelector('b')?.remove()});const head=$('#page-orders .v33-security-head');if(head){const left=head.firstElementChild;if(left&&!left.classList.contains('v37-security-brand')){const sec=currentSecurity37(),copy=document.createElement('div');copy.className='v37-security-copy';[...left.children].forEach(ch=>copy.appendChild(ch));left.className='v37-security-brand';const img=document.createElement('img');setRealLogo37(img,sec.ticker);left.append(img,copy)}else if(left){const img=left.querySelector('img'),sec=currentSecurity37();if(img&&img.dataset.ticker!==sec.ticker)setRealLogo37(img,sec.ticker)}}}
function ensureOrdersBack37(){const main=$('#page-orders .v33-orders-top>main');if(!main||$('#v37BackMarket'))return;const b=document.createElement('button');b.id='v37BackMarket';b.className='v37-back-market';b.type='button';b.textContent='← Market list';main.parentNode.insertBefore(b,main);b.onclick=()=>{document.documentElement.classList.remove('v37-ticker-selected');$('#page-orders .v33-orders-top>aside')?.scrollIntoView({behavior:'smooth',block:'start'})}}
function tickerRespond37(){decorateIssuerLogos37();ensureOrdersBack37();const main=$('#page-orders .v33-orders-top>main');if(main){main.classList.remove('v37-ticker-pulse');void main.offsetWidth;main.classList.add('v37-ticker-pulse');if(innerWidth<=760){document.documentElement.classList.add('v37-ticker-selected');setTimeout(()=>main.scrollIntoView({behavior:'smooth',block:'start'}),30)}}}

/* ---------------- Order ticket ---------------- */
let ticketStage37=0,ticket37=null;
function defaultTicket37(side='Buy',price=null){const s=currentSecurity37();return{side,portfolio:'Balanced Growth Fund',qty:10000,type:'Limit',price:price??s.price,tif:'Day',currency:s.currency,broker:'ABC Securities',route:'Best execution',venue:s.market||'Primary venue',settlement:'T+3',algo:'Work order / price discipline',allocation:'Single portfolio',rationale:'Rebalance toward the approved target while remaining inside mandate and liquidity limits.',approval:'Investment Director'}}
function ticketConsideration37(){return Math.max(0,num(ticket37.qty)*num(ticket37.price))}
function orderSummary37(){const s=currentSecurity37(),cons=ticketConsideration37(),issuerUse=Math.min(99,78+(s.ticker.charCodeAt(0)%16)),adv=Math.max(.6,Math.min(8.8,num(ticket37.qty)/4500)),cash=cons<550000?'Available':'Review';return `<div class="v37-ticket-summary"><div class="v37-ticket-stat"><span>Estimated consideration</span><strong>${money(cons,s.currency)}</strong><small>${Number(ticket37.qty||0).toLocaleString()} shares @ ${s.currency} ${Number(ticket37.price||0).toLocaleString(undefined,{maximumFractionDigits:2})}</small></div><div class="v37-ticket-stat"><span>Issuer limit after order</span><strong>${issuerUse}%</strong><small>House / mandate maximum 100%</small></div><div class="v37-ticket-stat"><span>Estimated ADV participation</span><strong>${adv.toFixed(1)}%</strong><small>Indicative; production uses licensed market volume</small></div><div class="v37-ticket-stat"><span>Funding / availability</span><strong>${cash}</strong><small>${ticket37.side==='Sell'?'Available position quantity checked':'Order-eligible cash and settlement reserve'}</small></div></div>`}
function controls37(){const cons=ticketConsideration37(),warn=cons>550000;return `<div class="v37-control-list"><div class="v37-control-row"><i></i><span><strong>Mandate eligibility</strong><small>Security, venue and order type permitted</small></span><em>Pass</em></div><div class="v37-control-row ${warn?'warn':''}"><i></i><span><strong>Issuer concentration</strong><small>Pro-forma exposure after order</small></span><em>${warn?'Review':'Pass'}</em></div><div class="v37-control-row"><i></i><span><strong>${ticket37.side==='Sell'?'Position availability':'Cash & settlement'}</strong><small>${ticket37.side==='Sell'?'IBOR settled + reserved quantity':'Cash ledger, reservations and SSI'}</small></span><em>Pass</em></div><div class="v37-control-row"><i></i><span><strong>Liquidity / market impact</strong><small>Participation and implementation cost check</small></span><em>Pass</em></div><div class="v37-control-row"><i></i><span><strong>Duplicate / wash control</strong><small>Same security, portfolio and direction reviewed</small></span><em>Clear</em></div></div>`}
function ticketPane37(){if(ticketStage37===0)return `<section class="v37-ticket-pane active"><div class="v37-order-side"><button type="button" class="${ticket37.side==='Buy'?'active buy':''}" data-v37-side="Buy">Buy</button><button type="button" class="${ticket37.side==='Sell'?'active sell':''}" data-v37-side="Sell">Sell</button></div><div class="v37-form"><label class="v37-field"><span>Portfolio *</span><select class="v37-select" id="v37Portfolio"><option>Balanced Growth Fund</option><option>USD Equity Fund</option><option>Income Fund</option><option>Zimbabwe Opportunities</option></select></label><label class="v37-field"><span>Order type</span><select class="v37-select" id="v37OrderType"><option>Limit</option><option>Market</option><option>Market on close</option><option>Stop limit</option></select></label><label class="v37-field wide"><span>Quantity *</span><div class="v37-qty-row"><input class="v37-input" id="v37Qty" type="number" min="1" step="100" value="${esc(ticket37.qty)}"><div class="v37-qty-presets"><button type="button" data-qty="5000">5k</button><button type="button" data-qty="10000">10k</button><button type="button" data-qty="25000">25k</button></div></div></label><label class="v37-field"><span>Limit / reference price</span><input class="v37-input" id="v37Price" type="number" min="0" step="0.01" value="${esc(ticket37.price)}"></label><label class="v37-field"><span>Time in force</span><select class="v37-select" id="v37Tif"><option>Day</option><option>GTC</option><option>IOC</option><option>FOK</option></select></label><label class="v37-field wide"><span>Investment / implementation rationale</span><textarea class="v37-textarea" id="v37Rationale">${esc(ticket37.rationale)}</textarea></label></div></section>`;
if(ticketStage37===1)return `<section class="v37-ticket-pane active"><div class="v37-form"><label class="v37-field"><span>Broker / route *</span><select class="v37-select" id="v37Broker"><option>ABC Securities</option><option>IH Securities</option><option>Morgan & Co</option><option>Lynton Edwards</option></select></label><label class="v37-field"><span>Routing approach</span><select class="v37-select" id="v37Route"><option>Best execution</option><option>Directed broker</option><option>DMA / electronic</option><option>Care order</option></select></label><label class="v37-field"><span>Venue</span><select class="v37-select" id="v37Venue"><option>${esc(currentSecurity37().market)}</option><option>Primary market</option></select></label><label class="v37-field"><span>Settlement</span><select class="v37-select" id="v37Settlement"><option>T+3</option><option>T+2</option><option>Same day</option></select></label><label class="v37-field wide"><span>Execution instruction</span><select class="v37-select" id="v37Algo"><option>Work order / price discipline</option><option>Participate with volume</option><option>Block / negotiated</option><option>Urgent completion</option></select></label><label class="v37-field"><span>Allocation</span><select class="v37-select" id="v37Allocation"><option>Single portfolio</option><option>Pro-rata allocation</option><option>Manual allocation after fill</option></select></label><label class="v37-field"><span>Approval route</span><select class="v37-select" id="v37Approval"><option>Investment Director</option><option>Independent dealer checker</option><option>Risk + Investment Director</option></select></label></div></section>`;
if(ticketStage37===2)return `<section class="v37-ticket-pane active"><div class="v37-kicker">PRE-TRADE CONTROL SNAPSHOT</div><h3 style="font-size:15px;margin:4px 0 7px">Controls before the instruction can be released</h3><p style="font-size:10px;color:#6f7e92;margin:0 0 8px">All controls use the proposed order, current portfolio state and effective mandate rules. A warning requires evidence or independent approval; it is not silently overridden.</p>${controls37()}<label class="v37-field wide" style="margin-top:10px"><span>Control / override rationale</span><textarea class="v37-textarea" id="v37ControlNote" placeholder="Required only if a warning is escalated or an approved override is requested."></textarea></label></section>`;
const s=currentSecurity37();return `<section class="v37-ticket-pane active"><div class="v37-kicker">REVIEW & SUBMIT</div><h3 style="font-size:15px;margin:4px 0 10px">One controlled instruction</h3><div class="v37-source-proof"><div><span>Security</span><strong>${esc(s.ticker)}</strong><small>${esc(s.name)}</small></div><div><span>Direction</span><strong>${esc(ticket37.side)}</strong><small>${Number(ticket37.qty||0).toLocaleString()} shares</small></div><div><span>Price</span><strong>${esc(s.currency)} ${Number(ticket37.price||0).toLocaleString(undefined,{maximumFractionDigits:2})}</strong><small>${esc(ticket37.type)} · ${esc(ticket37.tif)}</small></div><div><span>Broker</span><strong>${esc(ticket37.broker)}</strong><small>${esc(ticket37.route)}</small></div></div>${controls37()}<div class="v37-ticket-stat" style="margin-top:10px"><span>Rationale</span><strong style="font-size:11px;line-height:1.45">${esc(ticket37.rationale||'No rationale entered')}</strong><small>Submission freezes this order version and routes it to ${esc(ticket37.approval)}.</small></div></section>`}
function syncTicketInputs37(){const map={v37Portfolio:'portfolio',v37OrderType:'type',v37Qty:'qty',v37Price:'price',v37Tif:'tif',v37Rationale:'rationale',v37Broker:'broker',v37Route:'route',v37Venue:'venue',v37Settlement:'settlement',v37Algo:'algo',v37Allocation:'allocation',v37Approval:'approval'};Object.entries(map).forEach(([id,k])=>{const e=$('#'+id);if(e){e.value=ticket37[k]??e.value;e.oninput=e.onchange=()=>{ticket37[k]=['qty','price'].includes(k)?num(e.value):e.value;const sum=$('#v37TicketSummary');if(sum)sum.innerHTML=orderSummary37()}}});$$('[data-v37-side]').forEach(b=>b.onclick=()=>{ticket37.side=b.dataset.v37Side;renderTicket37()});$$('[data-qty]').forEach(b=>b.onclick=()=>{ticket37.qty=+b.dataset.qty;renderTicket37()})}
function renderTicket37(){const root=$('#v37OrderTicket');if(!root)return;const s=currentSecurity37();root.innerHTML=`<header class="v37-ticket-head"><div class="v37-ticket-security"><img id="v37TicketLogo" alt="${esc(s.name)} logo"><div><div class="v37-kicker">ORDER TICKET · CONTROLLED OMS INSTRUCTION</div><h2>${esc(s.ticker)} · ${esc(s.name)}</h2><p>${esc(s.market)} · ${esc(s.currency)} · price and market values illustrative until licensed feed is connected</p></div></div><div class="v37-ticket-quote"><strong>${esc(s.currency)} ${Number(s.price).toLocaleString(undefined,{maximumFractionDigits:2})}</strong><span>Selected market context</span></div><button class="v37-ticket-close" type="button" aria-label="Close">×</button></header><nav class="v37-ticket-steps">${[['01','Instruction'],['02','Execution'],['03','Controls'],['04','Review']].map((x,i)=>`<button type="button" data-ticket-step="${i}" class="${i===ticketStage37?'active':i<ticketStage37?'done':''}"><span>${x[0]}</span><strong>${x[1]}</strong></button>`).join('')}</nav><div class="v37-ticket-body"><div class="v37-ticket-grid"><article class="v37-ticket-panel"><div class="v37-ticket-panel-head"><div class="v37-kicker">${['ORDER INSTRUCTION','EXECUTION & ALLOCATION','PRE-TRADE CONTROLS','FINAL REVIEW'][ticketStage37]}</div><h3>${['Define exactly what should be traded','Define how the order should reach the market','See what can block or require approval','Confirm before creating the controlled order'][ticketStage37]}</h3></div><div class="v37-ticket-panel-body">${ticketPane37()}</div></article><aside class="v37-ticket-panel"><div class="v37-ticket-panel-head"><div class="v37-kicker">LIVE ORDER IMPACT</div><h3>What this instruction means</h3><p>Updates from the ticket inputs before submission.</p></div><div class="v37-ticket-panel-body" id="v37TicketSummary">${orderSummary37()}</div></aside></div></div><footer class="v37-ticket-footer"><small>Draft state is local to this prototype. Production creates immutable order versions and server-side approvals.</small><div><button class="v37-btn" id="v37TicketSave">Save draft</button><button class="v37-btn" id="v37TicketBack" ${ticketStage37===0?'disabled':''}>Back</button><button class="v37-btn primary" id="v37TicketNext">${ticketStage37===3?'Submit for approval':'Continue'}</button></div></footer>`;setRealLogo37($('#v37TicketLogo'),s.ticker);$('.v37-ticket-close',root).onclick=closeTicket37;$$('[data-ticket-step]',root).forEach(b=>b.onclick=()=>{const n=+b.dataset.ticketStep;if(n<=ticketStage37){ticketStage37=n;renderTicket37()}});syncTicketInputs37();$('#v37TicketBack').onclick=()=>{ticketStage37=Math.max(0,ticketStage37-1);renderTicket37()};$('#v37TicketSave').onclick=()=>{try{localStorage.setItem('matanho-v37-order-draft',JSON.stringify({security:s,ticket:ticket37,stage:ticketStage37}))}catch(e){}toast37('Order draft saved',`${s.ticker} ${ticket37.side.toLowerCase()} instruction saved at stage ${ticketStage37+1}.`)};$('#v37TicketNext').onclick=()=>{if(ticketStage37===0&&(!ticket37.portfolio||num(ticket37.qty)<=0||num(ticket37.price)<=0))return toast37('Complete the instruction','Portfolio, quantity and a valid price are required.','error');if(ticketStage37<3){ticketStage37++;renderTicket37();return}submitTicket37()}}
function openTicket37(side='Buy',price=null){let b=$('#v37OrderBackdrop'),r=$('#v37OrderTicket');if(!b){b=document.createElement('div');b.id='v37OrderBackdrop';document.body.appendChild(b);b.onclick=closeTicket37}if(!r){r=document.createElement('section');r.id='v37OrderTicket';r.setAttribute('role','dialog');r.setAttribute('aria-modal','true');document.body.appendChild(r)}ticketStage37=0;ticket37=defaultTicket37(side,price);renderTicket37();b.classList.add('show');r.classList.add('show');document.body.style.overflow='hidden'}
function closeTicket37(){$('#v37OrderBackdrop')?.classList.remove('show');$('#v37OrderTicket')?.classList.remove('show');document.body.style.overflow=''}
