function parseCsv37(text){const lines=String(text||'').split(/\r?\n/).filter(x=>x.trim());if(!lines.length)return[];const split=l=>{let a=[],q=false,v='';for(let i=0;i<l.length;i++){const c=l[i];if(c==='"'){if(q&&l[i+1]==='"'){v+='"';i++}else q=!q}else if(c===','&&!q){a.push(v.trim());v=''}else v+=c}a.push(v.trim());return a};const head=split(lines[0]);return lines.slice(1).map(l=>Object.fromEntries(split(l).map((v,i)=>[head[i]||`Column ${i+1}`,v])))}
