function riskTrendSvg37(){const current=[2.12,2.08,2.01,1.96,1.89,1.93,1.86,1.82,1.78,1.84],stress=[1.92,1.84,1.73,1.61,1.49,1.42,1.35,1.31,1.28,1.36],labs=['Now','T+3','T+7','T+10','T+14','T+18','T+21','T+24','T+27','T+30'],W=760,H=280,L=58,R=26,T=22,B=50,min=1,max=2.4,x=i=>L+(W-L-R)*i/(current.length-1),y=v=>T+(H-T-B)*(1-(v-min)/(max-min)),path=a=>a.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');let s=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Thirty day liquidity cover with stress case and house floor">`;[1,1.25,1.5,2,2.4].forEach(v=>{const yy=y(v);s+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#e6ebf2"/><text x="${L-10}" y="${yy+4}" text-anchor="end">${v.toFixed(v===1.25?2:1)}×</text>`});labs.forEach((lab,i)=>{if(i%2&&i!==labs.length-1)return;s+=`<text x="${x(i)}" y="${H-18}" text-anchor="${i===0?'start':i===labs.length-1?'end':'middle'}">${lab}</text>`});const fy=y(1.25);s+=`<line x1="${L}" x2="${W-R}" y1="${fy}" y2="${fy}" stroke="#d48c1b" stroke-width="2" stroke-dasharray="6 5"/><path d="${path(current)}" fill="none" stroke="#0b9aa7" stroke-width="2.6"/><path d="${path(stress)}" fill="none" stroke="#7357e8" stroke-width="2.6"/>`;current.forEach((v,i)=>s+=`<circle cx="${x(i)}" cy="${y(v)}" r="2.5" fill="#0b9aa7"/>`);stress.forEach((v,i)=>s+=`<circle cx="${x(i)}" cy="${y(v)}" r="2.5" fill="#7357e8"/>`);s+=`<text class="v37-axis-title" x="${L}" y="13">LIQUIDITY COVER (×)</text><text class="v37-axis-title" x="${W-R}" y="${H-4}" text-anchor="end">FORECAST DAY</text></svg>`;return s}
function factorChart37(){const vals=[['Equity',82],['FX',68],['Rates',44],['Credit',57],['Liquidity',76],['Private marks',63]],W=700,H=270,L=104,R=35,T=20,B=32,max=100,barH=25,gap=12,x=v=>L+(W-L-R)*v/max;let s=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Risk factor contribution scores">`;[0,25,50,75,100].forEach(v=>{const xx=x(v);s+=`<line x1="${xx}" x2="${xx}" y1="${T}" y2="${H-B}" stroke="#e6ebf2"/><text x="${xx}" y="${H-9}" text-anchor="middle">${v}</text>`});vals.forEach(([n,v],i)=>{const yy=T+i*(barH+gap);s+=`<text x="${L-10}" y="${yy+17}" text-anchor="end">${n}</text><rect x="${L}" y="${yy}" width="${W-L-R}" height="${barH}" rx="6" fill="#f0f3f7"/><rect x="${L}" y="${yy}" width="${x(v)-L}" height="${barH}" rx="6" fill="${v>75?'#7357e8':v>60?'#315ee9':'#0b9aa7'}"/><text x="${Math.min(W-R-7,x(v)+8)}" y="${yy+17}" fill="#314257" stroke="none">${v}/100</text>`});s+=`<text class="v37-axis-title" x="${W-R}" y="${H-2}" text-anchor="end">RISK CONTRIBUTION SCORE</text></svg>`;return s}
function riskLimitRows37(){return riskLimits37.map((r,i)=>{const use=Math.max(0,Math.min(120,r.current/r.threshold*100)),warn=use>=85;return `<tr><td><strong>${esc(r.metric)}</strong><small>${esc(r.scope)}</small></td><td class="v37-limit-usage ${warn?'warn':''}">${r.current}${esc(r.unit)}<i><u style="--w:${Math.min(100,use)}%"></u></i></td><td>${r.stress}${esc(r.unit)}</td><td>${r.threshold}${esc(r.unit)}</td><td>${Math.max(0,r.threshold-r.current).toFixed(r.unit==='×'?2:1)}${esc(r.unit)}</td><td>${esc(r.action)}</td><td><span class="v37-chip ${r.state==='Within'?'good':'warn'}">${esc(r.state)}</span></td><td><button class="v37-btn" data-limit-edit="${i}" style="height:29px;padding:0 8px">Edit</button></td></tr>`}).join('')}
function riskScenarioCalc37(){const eq=num($('#v37RiskEq')?.value??-20),fx=num($('#v37RiskFx')?.value??-15),rates=num($('#v37RiskRates')?.value??150),red=num($('#v37RiskRed')?.value??10);const loss=(eq*.21+fx*.09-rates*.0016-red*.12),liq=Math.max(.72,1.84-red*.031+eq*.004),cash=1.12-red*.136;$('#v37RiskLoss')&&($('#v37RiskLoss').textContent=`${loss>=0?'+':''}${loss.toFixed(2)}%`);$('#v37RiskLiq')&&($('#v37RiskLiq').textContent=`${liq.toFixed(2)}×`);$('#v37RiskCash')&&($('#v37RiskCash').textContent=`${cash<0?'−':''}US$ ${Math.abs(cash).toFixed(2)}m`);const state=liq<1.25||loss<-8?'Escalate':liq<1.5||loss<-5?'Review':'Within';$('#v37RiskState')&&($('#v37RiskState').textContent=state);return{loss,liq,cash,state}}
