function buildRisk37(){const p=$('#page-risk');if(!p)return;p.className='page v37-risk';p.innerHTML=`<div class="v37-risk-shell"><header class="v37-risk-head"><div><div class="v37-kicker">PORTFOLIO RISK · LIMITS · STRESS · LIQUIDITY · COMPLIANCE</div><h1>Risk & Compliance</h1><p>One decision cockpit for forward risk, liquidity, effective mandate limits and compliance cases. Every imported population carries a source and as-of state.</p></div><div class="v37-risk-actions"><button class="v37-btn" id="v37RiskImportPositions">Import positions</button><button class="v37-btn" id="v37RiskImportLimits">Import limits</button><button class="v37-btn" id="v37RiskReport">Compliance report</button><button class="v37-btn primary" id="v37RiskRunTop">Run stress</button></div></header><section class="v37-risk-banner"><div><span>Current risk posture</span><strong>Within hard mandate · 2 amber constraints</strong><small>Most immediate decision: Delta issuer headroom before proposed order release.</small></div><div><span>Closest limit</span><strong>Delta · 91%</strong><small>0.90% headroom</small></div><div><span>Severe stress</span><strong>−8.42%</strong><small>Cross-asset scenario</small></div><div><span>30d liquidity</span><strong>1.84×</strong><small>Floor 1.25×</small></div><div><span>Open compliance</span><strong>3</strong><small>1 enhanced review</small></div></section><section class="v37-risk-kpis"><article class="v37-risk-kpi"><span>99% 1d VaR</span><strong>2.18%</strong><small>−8 bps vs prior close</small></article><article class="v37-risk-kpi"><span>Expected shortfall</span><strong>3.04%</strong><small>99% tail mean</small></article><article class="v37-risk-kpi"><span>Liquidity cover</span><strong>1.84×</strong><small>30-day stressed</small></article><article class="v37-risk-kpi"><span>FX unhedged</span><strong>31.6%</strong><small>Whole portfolio NAV</small></article><article class="v37-risk-kpi"><span>Illiquid NAV</span><strong>15.4%</strong><small>Limit 25.0%</small></article><article class="v37-risk-kpi alert"><span>Human action</span><strong>5</strong><small>2 limits · 3 compliance</small></article></section><div class="v37-risk-grid"><article class="v37-risk-card v37-span-8"><div class="v37-risk-card-head"><div><div class="v37-kicker">FORWARD LIQUIDITY RISK</div><h2>30-day liquidity cover</h2><p>Current and stressed liquidity against the house floor. Axis labels and legend remain visible at all screen sizes.</p></div><span class="v37-chip info">Daily forecast</span></div><div class="v37-risk-card-body"><div class="v37-chart-box">${riskTrendSvg37()}</div></div><div class="v37-chart-legend"><span><i class="current"></i>Current forecast</span><span><i class="stress"></i>Severe stress</span><span><i class="floor"></i>House floor · 1.25×</span></div></article><aside class="v37-risk-card v37-span-4"><div class="v37-risk-card-head"><div><div class="v37-kicker">RISK BUDGET</div><h2>Budget utilisation</h2><p>Portfolio contribution against approved risk capacity.</p></div></div><div class="v37-risk-card-body"><div class="v37-ring-grid"><div class="v37-ring" style="--p:78%"><div><strong>78%</strong><small>risk budget</small></div></div><div class="v37-risk-bars"><div class="v37-risk-bar warn"><label><span>Issuer concentration</span><b>91%</b></label><i><u style="--w:91%"></u></i></div><div class="v37-risk-bar"><label><span>Tracking error</span><b>76%</b></label><i><u style="--w:76%"></u></i></div><div class="v37-risk-bar"><label><span>Liquidity</span><b>64%</b></label><i><u style="--w:64%"></u></i></div><div class="v37-risk-bar"><label><span>Private / Level 3</span><b>62%</b></label><i><u style="--w:62%"></u></i></div></div></div></div></aside><article class="v37-risk-card v37-span-7"><div class="v37-risk-card-head"><div><div class="v37-kicker">FACTOR LENS</div><h2>Risk contribution by factor</h2><p>Indicative contribution score; use drill-through for model and exposure evidence.</p></div></div><div class="v37-risk-card-body"><div class="v37-chart-box">${factorChart37()}</div></div><div class="v37-chart-legend"><span><i></i>Higher score = greater portfolio contribution</span><span>0 low · 100 high</span></div></article><aside class="v37-risk-card v37-span-5"><div class="v37-risk-card-head"><div><div class="v37-kicker">FACTOR / SLEEVE MAP</div><h2>Where risk is concentrated</h2><p>Click a cell to open the associated exposure view.</p></div></div><div class="v37-risk-card-body"><div class="v37-heat"><div></div>${['Listed','Fixed','Private','Real assets','Cash'].map(x=>`<div class="label">${x}</div>`).join('')}${[['Growth',[90,22,76,48,8]],['Rates',[26,88,42,53,18]],['FX',[68,33,59,47,36]],['Credit',[32,72,81,55,15]],['Liquidity',[47,36,79,64,12]]].map(([r,vs])=>`<div class="label">${r}</div>${vs.map((v,i)=>`<button class="cell" style="--heat:${v}" data-heat="${r}|${['Listed','Fixed','Private','Real assets','Cash'][i]}|${v}"><strong>${v}</strong><small>${v>75?'High':v>50?'Medium':'Low'}</small></button>`).join('')}`).join('')}</div></div></aside><article class="v37-risk-card v37-span-8"><div class="v37-risk-card-head"><div><div class="v37-kicker">SCENARIO LAB</div><h2>Build and run a portfolio stress</h2><p>Editable shocks update the impact immediately. Save or export only after the inputs and portfolio source are controlled.</p></div><span class="v37-chip info">Interactive</span></div><div class="v37-risk-card-body"><div class="v37-risk-scenario"><label>Equity shock<input class="v37-input" id="v37RiskEq" type="number" value="-20"><small>%</small></label><label>ZWG shock<input class="v37-input" id="v37RiskFx" type="number" value="-15"><small>% vs USD</small></label><label>Rates shock<input class="v37-input" id="v37RiskRates" type="number" value="150"><small>bps</small></label><label>Client redemption<input class="v37-input" id="v37RiskRed" type="number" value="10"><small>% AUM</small></label></div><div class="v37-risk-output"><div><span>Portfolio impact</span><strong id="v37RiskLoss">−8.15%</strong><small>Stressed P&L</small></div><div><span>Liquidity cover</span><strong id="v37RiskLiq">1.49×</strong><small>Floor 1.25×</small></div><div><span>Cash after redemption</span><strong id="v37RiskCash">−US$ 0.24m</strong><small>Before sales</small></div><div><span>Decision state</span><strong id="v37RiskState">Review</strong><small>Human judgement</small></div></div><div class="v37-risk-actions-row"><button class="v37-btn" id="v37RiskReset">Reset</button><button class="v37-btn" id="v37RiskSave">Save scenario</button><button class="v37-btn primary" id="v37RiskRun">Run scenario</button></div></div></article><aside class="v37-risk-card v37-span-4"><div class="v37-risk-card-head"><div><div class="v37-kicker">SOURCE POPULATIONS</div><h2>What risk is calculated from</h2><p>Import buttons register the source and preview rows before use.</p></div></div><div class="v37-risk-card-body"><div class="v37-import-sources"><div class="v37-source-card"><b>POS</b><span><strong>${riskImport37.positions?'Imported position snapshot':'IBOR positions'}</strong><small>${riskImport37.positions?`${riskImport37.positions.rows.length} rows · ${riskImport37.positions.asOf}`:'438 positions · 15:42 CAT'}</small></span><em>Current</em></div><div class="v37-source-card"><b>LIM</b><span><strong>${riskImport37.limits?'Imported limits':'Policy / mandate rules'}</strong><small>${riskImport37.limits?`${riskImport37.limits.rows.length} rows · ${riskImport37.limits.asOf}`:'Effective 01 Jul 2026'}</small></span><em>Current</em></div><div class="v37-source-card"><b>PX</b><span><strong>Price / FX snapshot</strong><small>Market close + approved FX</small></span><em>Current</em></div><div class="v37-source-card"><b>MOD</b><span><strong>Risk model set</strong><small>RM-2026-07 · approved</small></span><em>Valid</em></div></div></div></aside><article class="v37-risk-card v37-span-12"><div class="v37-risk-card-head"><div><div class="v37-kicker">MANDATE & HOUSE LIMITS</div><h2>Effective limit book</h2><p>Current and stressed usage against the exact rule version used by pre-trade controls.</p></div><button class="v37-btn" id="v37AddLimit">+ Draft limit</button></div><div class="v37-limit-table"><table><thead><tr><th>Limit</th><th>Current</th><th>Stress</th><th>Threshold</th><th>Headroom</th><th>Action</th><th>State</th><th></th></tr></thead><tbody id="v37RiskLimits">${riskLimitRows37()}</tbody></table></div></article><article class="v37-risk-card v37-span-6"><div class="v37-risk-card-head"><div><div class="v37-kicker">EARLY WARNING</div><h2>Signals requiring action</h2></div></div><div class="v37-risk-card-body"><div class="v37-risk-list"><div class="v37-risk-row clickable" data-risk-go="orders"><span><strong>Delta concentration approaching hard limit</strong><small>Proposed order moves stressed exposure above threshold</small></span><em>91%</em></div><div class="v37-risk-row clickable" data-risk-go="private-markets"><span><strong>September private calls exceed distributions</strong><small>Base-case net outflow US$ 1.46m</small></span><em>Watch</em></div><div class="v37-risk-row clickable" data-risk-go="valuation"><span><strong>Private valuation evidence stale</strong><small>Growth Equity IV · release impact</small></span><em>High</em></div></div></div></article><aside class="v37-risk-card v37-span-6"><div class="v37-risk-card-head"><div><div class="v37-kicker">COMPLIANCE CASES</div><h2>Human decision queue</h2></div><button class="v37-btn" id="v37NewRiskCase">+ Case</button></div><div class="v37-risk-card-body"><div class="v37-risk-list"><div class="v37-risk-row clickable" data-risk-go="onboarding"><span><strong>Enhanced source-of-funds review</strong><small>Horizon Pension Fund · US$ 480k</small></span><em>Today</em></div><div class="v37-risk-row clickable" data-risk-go="orders"><span><strong>Mandate exception review</strong><small>Balanced Growth · Delta order</small></span><em>38 min</em></div><div class="v37-risk-row clickable" data-risk-go="onboarding"><span><strong>KYC refresh programme</strong><small>6 records expire within 30 days</small></span><em>7 days</em></div></div></div></aside></div></div>`;['v37RiskEq','v37RiskFx','v37RiskRates','v37RiskRed'].forEach(id=>$('#'+id)?.addEventListener('input',riskScenarioCalc37));$('#v37RiskRun')?.addEventListener('click',()=>{const r=riskScenarioCalc37();toast37('Stress run complete',`Estimated impact ${r.loss.toFixed(2)}% · liquidity ${r.liq.toFixed(2)}× · ${r.state}.`)});$('#v37RiskRunTop')?.addEventListener('click',()=>$('#v37RiskRun')?.click());$('#v37RiskReset')?.addEventListener('click',()=>{[['v37RiskEq',-20],['v37RiskFx',-15],['v37RiskRates',150],['v37RiskRed',10]].forEach(([id,v])=>$('#'+id).value=v);riskScenarioCalc37()});$('#v37RiskSave')?.addEventListener('click',()=>toast37('Scenario saved','Shock set and outputs saved as a controlled working scenario.'));$('#v37RiskImportPositions')?.addEventListener('click',()=>openRiskImport37('positions'));$('#v37RiskImportLimits')?.addEventListener('click',()=>openRiskImport37('limits'));$('#v37RiskReport')?.addEventListener('click',()=>openRiskReport37());$$('[data-risk-go]',p).forEach(x=>x.onclick=()=>nav37(x.dataset.riskGo));$$('[data-heat]',p).forEach(x=>x.onclick=()=>{const [factor,sleeve,score]=x.dataset.heat.split('|');modal37({eyebrow:'RISK EXPOSURE',title:`${factor} · ${sleeve}`,subtitle:`Contribution score ${score}/100`,body:`<div class="v37-ticket-stat"><span>Exposure interpretation</span><strong>${+score>75?'High contribution — review concentration and stress transmission':+score>50?'Material contribution — monitor':'Low contribution'}</strong><small>Drill-through would resolve to positions, model sensitivities, scenario evidence and effective limits.</small></div>`})});$('#v37AddLimit')?.addEventListener('click',openLimitForm37);$$('[data-limit-edit]',p).forEach(b=>b.onclick=()=>openLimitForm37(+b.dataset.limitEdit));$('#v37NewRiskCase')?.addEventListener('click',()=>modal37({eyebrow:'COMPLIANCE CASE',title:'Create controlled risk / compliance case',subtitle:'Assign an owner, due date, affected portfolio/client and required evidence.',body:'<div class="v37-form"><label class="v37-field"><span>Case type</span><select class="v37-select"><option>Mandate exception</option><option>AML / KYC</option><option>Limit investigation</option><option>Operational risk</option></select></label><label class="v37-field"><span>Owner</span><select class="v37-select"><option>Risk</option><option>Compliance</option><option>MLRO</option></select></label><label class="v37-field wide"><span>Issue</span><textarea class="v37-textarea"></textarea></label></div>'}));riskScenarioCalc37()}
function openLimitForm37(i=null){const r=i==null?{metric:'Single issuer',scope:'All portfolios',threshold:10,unit:'%',action:'Warn'}:riskLimits37[i],m=modal37({eyebrow:'RISK LIMIT',title:i==null?'Create draft limit':'Amend limit',subtitle:'Draft changes never affect dealing until independent approval and effective dating.',body:`<div class="v37-form"><label class="v37-field"><span>Metric</span><input class="v37-input" id="v37LimitMetric" value="${esc(r.metric)}"></label><label class="v37-field"><span>Scope</span><input class="v37-input" id="v37LimitScope" value="${esc(r.scope)}"></label><label class="v37-field"><span>Threshold</span><input class="v37-input" type="number" id="v37LimitThreshold" value="${esc(r.threshold)}"></label><label class="v37-field"><span>Unit</span><select class="v37-select" id="v37LimitUnit"><option>%</option><option>×</option><option>US$</option></select></label><label class="v37-field"><span>Action</span><select class="v37-select" id="v37LimitAction"><option>Warn</option><option>Approval</option><option>Block</option></select></label><label class="v37-field"><span>Effective date</span><input class="v37-input" type="date" value="2026-09-01"></label></div>`,footer:`<span>Maker/checker required before activation.</span><div><button class="v37-btn" id="v37LimitCancel">Cancel</button><button class="v37-btn primary" id="v37LimitSave">Save draft</button></div>`});$('#v37LimitUnit',m).value=r.unit;$('#v37LimitAction',m).value=r.action;$('#v37LimitCancel',m).onclick=m._close;$('#v37LimitSave',m).onclick=()=>{const v={metric:$('#v37LimitMetric',m).value,scope:$('#v37LimitScope',m).value,current:i==null?0:r.current,stress:i==null?0:r.stress,threshold:num($('#v37LimitThreshold',m).value),unit:$('#v37LimitUnit',m).value,action:$('#v37LimitAction',m).value,state:'Draft'};if(i==null)riskLimits37.push(v);else riskLimits37[i]=v;m._close();buildRisk37();toast37('Draft limit saved','Independent approval is required before the rule becomes effective.')}}
function openRiskReport37(){modal37({eyebrow:'RISK REPORT PREVIEW',title:'Daily Risk & Compliance Pack',subtitle:'Preview from the current working population.',wide:true,body:`<div class="v37-doc-preview"><article class="v37-paper"><div class="v37-paper-brand"><strong>matanho · Risk Office</strong><span>CONTROLLED MANAGEMENT REPORT<br>01 Sep 2026 · 04:08 CAT</span></div><h1>Daily Risk & Compliance Pack</h1><div class="meta">Whole portfolio · governed positions / limits / risk model set</div><h2>Executive risk position</h2><p>The portfolio remains within hard mandate. Delta issuer exposure is the closest binding constraint, while stressed 30-day liquidity remains above the 1.25× house floor.</p><table><tr><th>Measure</th><th>Current</th><th>Limit / floor</th><th>State</th></tr><tr><td>99% 1d VaR</td><td>2.18%</td><td>3.00%</td><td>Within</td></tr><tr><td>Delta issuer exposure</td><td>9.10%</td><td>10.00%</td><td>Amber</td></tr><tr><td>30d liquidity cover</td><td>1.84×</td><td>1.25×</td><td>Within</td></tr></table><h2>Human actions</h2><ul><li>Review proposed Delta order against issuer headroom.</li><li>Complete one enhanced source-of-funds review.</li><li>Resolve independent evidence for the private valuation exception.</li></ul><div class="v37-signature"><div>Prepared by · Risk Analytics</div><div>Independent reviewer · Pending</div></div></article></div>`})}

/* ---------------- Documents: preview means preview ---------------- */
function documentPreviewBody37(title,related,owner,updated,access,status,type){const lower=(type+' '+title).toLowerCase();let content='';if(/agreement|mandate|legal/.test(lower))content=`<h2>1. Appointment and mandate</h2><p>The client appoints the investment manager to manage the portfolio in accordance with the approved investment mandate, risk constraints and dealing authorities recorded in the client master.</p><h2>2. Investment restrictions</h2><table><tr><th>Control</th><th>Approved position</th></tr><tr><td>Single issuer maximum</td><td>10.00% of portfolio NAV</td></tr><tr><td>Minimum liquidity</td><td>5.00% of NAV</td></tr><tr><td>Permitted markets</td><td>ZSE / VFEX and approved cash instruments</td></tr></table><h2>3. Reporting and authority</h2><p>Official statements, fee calculations and changes to authorised signatories are subject to the controlled maker/checker process.</p>`;else if(/policy|valuation|governance/.test(lower))content=`<h2>Policy objective</h2><p>This controlled policy defines the valuation hierarchy, price-source precedence, stale-price thresholds, override evidence and independent release authority.</p><h2>Control hierarchy</h2><table><tr><th>Level</th><th>Evidence</th><th>Authority</th></tr><tr><td>Listed securities</td><td>Approved exchange / broker close</td><td>Fund Accounting</td></tr><tr><td>Private assets</td><td>Administrator / manager NAV + independent support</td><td>Valuation checker</td></tr><tr><td>Overrides</td><td>Documented rationale and source snapshot</td><td>Independent approval</td></tr></table>`;else if(/regulatory|attestation/.test(lower))content=`<h2>Attestation</h2><p>The undersigned confirms that the reported population has been reconciled to governed books and that material exceptions have been disclosed.</p><table><tr><th>Population</th><th>Result</th></tr><tr><td>Total AUM</td><td>US$ 84.62m</td></tr><tr><td>Client master population</td><td>418 records</td></tr><tr><td>Validation</td><td>100% complete</td></tr></table><h2>Submission control</h2><p>Filing remains blocked until compliance and finance attestations are complete.</p>`;else content=`<h2>Document summary</h2><p>This is the controlled preview of the selected document version. The related business record, owner, access policy, update timestamp and publication state remain attached to the file.</p><h2>Evidence record</h2><table><tr><th>Related record</th><td>${esc(related)}</td></tr><tr><th>Owner</th><td>${esc(owner)}</td></tr><tr><th>Access</th><td>${esc(access)}</td></tr><tr><th>Status</th><td>${esc(status)}</td></tr></table><h2>Document content</h2><p>Supporting schedules, approval notes, source snapshots and signatures are retained with the authoritative version in the document vault.</p>`;return `<div class="v37-preview-toolbar"><div><button class="v37-btn" id="v37PreviewClose">Close preview</button><span>Page 1 of 1 · controlled representation</span></div><div><button class="v37-btn" id="v37PreviewZoom">Fit width</button><button class="v37-btn" id="v37PreviewPrint">Print / PDF</button></div></div><div class="v37-doc-preview"><article class="v37-paper"><div class="v37-paper-brand"><strong>matanho</strong><span>CONTROLLED DOCUMENT<br>${esc(updated)}</span></div><h1>${esc(title)}</h1><div class="meta">${esc(type)} · ${esc(related)} · owner ${esc(owner)}</div>${content}<div class="v37-signature"><div>Document owner · ${esc(owner)}</div><div>Control state · ${esc(status)}</div></div></article></div>`}
function openDocumentPreview37(row){const cells=$$('td',row),title=cells[0]?.querySelector('strong')?.textContent||'Controlled document',type=cells[0]?.querySelector('small')?.textContent||'Document',related=cells[1]?.textContent||'—',owner=cells[2]?.textContent||'—',updated=cells[3]?.textContent||'—',access=cells[4]?.textContent||'—',status=cells[5]?.textContent||'Current',host=$('#v33DocPreview');if(!host)return;host.hidden=false;host.innerHTML=documentPreviewBody37(title,related,owner,updated,access,status,type);$('#v37PreviewClose',host).onclick=()=>{host.hidden=true;host.innerHTML=''};$('#v37PreviewPrint',host).onclick=()=>window.print();$('#v37PreviewZoom',host).onclick=()=>{host.querySelector('.v37-paper').style.width='100%';toast37('Preview fitted','The document preview is fitted to the available width.')};host.scrollIntoView({behavior:'smooth',block:'start'})}
function bindPreview37(){document.addEventListener('click',e=>{const row=e.target.closest?.('#page-vault [data-doc-index],#page-documents [data-doc-index]');if(row){e.preventDefault();e.stopImmediatePropagation();openDocumentPreview37(row)}},{capture:true})}

