const MODEL_KEY37='matanho-v37-models';
let models37=window.__mxData._models37||[{id:'MOD-034',name:'Listed Equity Risk Model',purpose:'Portfolio VaR / stress',version:'4.2',owner:'Risk Analytics',validation:'18 Sep 2026',state:'Production',dataset:'Whole Portfolio Positions v12',method:'Historical simulation + factor mapping',tests:true,validator:'Independent Model Risk',monitor:'Daily drift / monthly performance'},{id:'MOD-029',name:'Liquidity Projection Model',purpose:'30-day liquidity cover',version:'3.1',owner:'Risk Analytics',validation:'05 Sep 2026',state:'Validation due',dataset:'Cash + flows + market liquidity v9',method:'Scenario cashflow ladder',tests:true,validator:'Independent Model Risk',monitor:'Daily forecast error'},{id:'MOD-021',name:'Private Asset Fair Value DCF',purpose:'Level 3 valuation support',version:'2.4',owner:'Valuation',validation:'30 Oct 2026',state:'Production',dataset:'Private Asset Valuation Inputs v6',method:'DCF / terminal multiple',tests:true,validator:'Valuation Committee',monitor:'Quarterly backtest'}];
try{const saved=(window.mx&&window.mx.live&&window.mx.strict('model-governance'))?null:JSON.parse(localStorage.getItem(MODEL_KEY37)||'null');if(Array.isArray(saved)&&saved.length)models37=saved}catch(e){}
let modelSelected37=models37[0]?.id,modelWizard37={step:0,draft:null};
